import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { SnapshotStorage } from "./config.js";

// Where camera snapshots live. Callers check permissions and write the audit log; a store only
// keeps bytes. Names are generated by the API (a UUID plus ".jpg"), never taken from a request.
export interface SnapshotStore {
  save(name: string, image: Buffer): Promise<void>;
  // Null when the snapshot doesn't exist.
  read(name: string): Promise<Buffer | null>;
}

export function folderStore(dir: string): SnapshotStore {
  return {
    async save(name, image) {
      // Created on first use, so starting the API never touches the filesystem.
      await mkdir(dir, { recursive: true });
      await writeFile(join(dir, name), image);
    },
    async read(name) {
      try {
        return await readFile(join(dir, name));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw error;
      }
    },
  };
}

interface SupabaseOptions {
  url: string;
  serviceRoleKey: string;
  bucket: string;
  fetch?: typeof fetch;
}

// Supabase Storage through its REST API. The bucket is private, and the service-role key never
// leaves the server, so the only way to see a snapshot is through the API's audited endpoint.
export function supabaseStore({ url, serviceRoleKey, bucket, fetch: fetcher = fetch }: SupabaseOptions): SnapshotStore {
  const headers: Record<string, string> = { apikey: serviceRoleKey };
  // Legacy service-role keys are JWTs and also go in Authorization; newer secret keys don't.
  if (serviceRoleKey.startsWith("eyJ")) headers.authorization = `Bearer ${serviceRoleKey}`;
  const objectUrl = (name: string) =>
    `${url}/storage/v1/object/${encodeURIComponent(bucket)}/${encodeURIComponent(name)}`;

  return {
    async save(name, image) {
      const response = await fetcher(objectUrl(name), {
        method: "POST",
        headers: { ...headers, "content-type": "image/jpeg", "x-upsert": "false" },
        body: new Uint8Array(image),
        signal: AbortSignal.timeout(10_000),
      });
      if (!response.ok) throw new Error(`Snapshot upload failed (${response.status})`);
    },
    async read(name) {
      const response = await fetcher(
        `${url}/storage/v1/object/authenticated/${encodeURIComponent(bucket)}/${encodeURIComponent(name)}`,
        { headers, signal: AbortSignal.timeout(10_000) },
      );
      // Storage answers a missing object with 400 or 404 depending on the version.
      if (response.status === 404 || response.status === 400) return null;
      if (!response.ok) throw new Error(`Snapshot download failed (${response.status})`);
      return Buffer.from(await response.arrayBuffer());
    },
  };
}

export function snapshotStoreFor(storage: SnapshotStorage): SnapshotStore | undefined {
  if (storage.kind === "supabase") return supabaseStore(storage);
  if (storage.kind === "folder") return folderStore(storage.dir);
  return undefined;
}
